pub const StdioKind = enum {
    stdin,
    stdout,
    stderr,
    pub fn get(__cp_s: []const u8) ?@This() { return std.meta.stringToEnum(@This(), __cp_s); }
    pub fn has(__cp_s: []const u8) bool { return std.meta.stringToEnum(@This(), __cp_s) != null; }
    pub fn fromName(__cp_s: []const u8) ?@This() { return std.meta.stringToEnum(@This(), __cp_s); }
    pub fn name(__cp_self: @This()) []const u8 { return @tagName(__cp_self); }

pub fn toFd(self: StdioKind) bun.FD {
            return (switch (self) {
.stdin => .stdin(),
.stdout => .stdout(),
.stderr => .stderr(),
});
    }

pub fn toNum(self: StdioKind) c_int {
            return (switch (self) {
.stdin => 0,
.stdout => 1,
.stderr => 2,
});
    }
};

pub fn DerefGuard(comptime T: type) type {
    return struct {
        ptr: ?*T,
        __cp_dropped: bool = false,

pub fn __cp_deinit(self: *@This()) void {
            if (self.__cp_dropped) return;
            self.__cp_dropped = true;
                {
                    if (self.ptr) |p| {
                        _ = &p;
                        _ = p.deref();
                    }
                }
        }
    };
}

pub const Flags = packed struct(u8) {
    is_sync: bool = false,
    killed: bool = false,
    has_stdin_destructor_called: bool = false,
    finalized: bool = false,
    deref_on_stdin_destroyed: bool = false,
    is_stdin_a_readable_stream: bool = false,
    owns_terminal: bool = false,
    _: u1 = 0,
};

pub const WaitThreadPoll = struct {
    ref_count: std.atomic.Value(u32) = std.atomic.Value(u32).init(0),
    poll_ref: Async.KeepAlive = .{},
};

pub const Poll = union(enum) {
    poll_ref: ?*Async.FilePoll,
    wait_thread: WaitThreadPoll,
};

pub const Source = union(enum) {
    blob: jsc.WebCore.Blob.Any,
    array_buffer: jsc.ArrayBuffer.Strong,
    detached: void,

pub fn memoryCost(self: Source) usize {
            return (switch (self) {
.blob => self.blob.memoryCost(),
.array_buffer => 0,
.detached => 0,
});
    }

pub fn slice(self: *const Source) []const u8 {
            return (switch (self.*) {
.blob => self.blob.slice(),
.array_buffer => self.array_buffer.slice(),
else => @panic("Invalid source"),
});
    }

pub fn detach(self: *Source) void {
            switch (self.*) {
.blob => {
_ = self.blob.detach();
},
.array_buffer => {
_ = self.array_buffer.deinit();
},
else => {

},
}
            self.* = .detached;
    }
};

pub const TestingAPIs = struct {

pub fn injectStdioReadError(globalThis: *jsc.JSGlobalObject, callframe: *jsc.CallFrame) bun.JSError!jsc.JSValue {
            const args = callframe.argumentsAsArray(2);
            const subprocess_value = args[0];
            const kind_value = args[1];
            const sub_opt = Subprocess.fromJS(subprocess_value);
            if ((sub_opt == null)) {
                return globalThis.throw("first argument must be a Subprocess", .{});
            }
            const subprocess = sub_opt.?;
            var kind_str = try kind_value.toBunString(globalThis);
            _ = &kind_str;
